// Builds work/evidence-manifest.json. Commands 01-29 are complete when this runs.
// This command's own out, err, and exit are written by the wrapper after exit.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

function rec(path) {
  const data = readFileSync(resolve(path));
  return { path: path.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function walk(dir, out) {
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name);
    const st = statSync(abs);
    if (st.isDirectory()) walk(abs, out);
    else out.push(relative(resolve('.'), abs).replaceAll('\\', '/'));
  }
}
const outputs = [];
walk(resolve('work'), outputs);
outputs.sort();
const skip = new Set(['work/evidence-manifest.json', 'work/evidence-supplement.json']);
const outputRecs = outputs.filter((p) => !skip.has(p)).map(rec);

const inputs = [
  'brief.md', 'TASK.md', 'templates/result.md',
  'inputs/00_0100_50000020.decoded.bin', 'inputs/02_0106_458c0020.decoded.bin',
].map(rec);
const sourcePaths = [
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/scripts/accept_v1.mjs',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/scripts/save_v3.mjs',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/out/overlay-changed-bytes.csv',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/out/save-table-v3.json',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/out/accept-v1.jsonl',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/result.md',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/scripts/fix_v1.mjs',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/scripts/accept_lib_v4.mjs',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/out/overlay-changed-bytes.csv',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/result.md',
  'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs',
  'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/observe_c1.mjs',
  'ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/accept_table_c3.json',
  'ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs',
  'audit/previous-review.md',
];
const missing = sourcePaths.filter((p) => !existsSync(resolve(p)));
if (missing.length) throw new Error('missing sources ' + missing.join(','));
const sources = sourcePaths.map(rec);

function commandRec(n) {
  const nn = String(n).padStart(2, '0');
  const cmdText = readFileSync(resolve('work/out/cmd/' + nn + '.cmd.txt'), 'utf8');
  const exitDoc = JSON.parse(readFileSync(resolve('work/out/cmd/' + nn + '.exit'), 'utf8'));
  return {
    n,
    requested: (cmdText.match(/^requested: (.*)$/m) || [])[1] || '',
    status: exitDoc.status,
    wrapper_sha256: exitDoc.wrapper_sha256,
    scripts: exitDoc.scripts || [],
    files: {
      cmd: rec('work/out/cmd/' + nn + '.cmd.txt'),
      out: rec('work/out/cmd/' + nn + '.out'),
      err: rec('work/out/cmd/' + nn + '.err'),
      exit: rec('work/out/cmd/' + nn + '.exit'),
    },
  };
}
const commands = [];
for (let n = 1; n <= 29; n++) commands.push(commandRec(n));
const dynamic = [];
for (const tag of ['t8v1', 't8v2', 't8v3', 't8v4', 't8v5', 't8v6', 't8r1', 't8r2', 't8r3', 't8r4', 't8r5']) {
  const path = 'work/out/import-inventory-' + tag + '.json';
  dynamic.push({ tag, file: rec(path), rows: JSON.parse(readFileSync(resolve(path), 'utf8')).rows });
}
const doc = {
  task: 'T8',
  brief_sha256: inputs[0].sha256,
  note: 'Correction round. Experiment versions t8r1, t8r2, t8r3, t8r4, t8r5 are commands 20, 21, 23, 24, and 29. Commands 18 and 19 are the table check. Commands 27 and 28 are save diagnostics. t8r5 wrote work/out/reference-v1.json and ended ok:false because the commit appended no fresh E. This manifest is the next command. Its own out, err, and exit are sealed by the supplement.',
  inputs, sources, outputs: outputRecs, commands, dynamic_imports: dynamic,
  reference_v1: rec('work/out/reference-v1.json'),
  tool_versions: { node: process.version, wrapper: commands[0].wrapper_sha256 },
};
writeFileSync(resolve('work/evidence-manifest.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, outputs: outputRecs.length, commands: commands.length, brief: doc.brief_sha256 }) + '\n');
